"""Migrated Meridian CRM 4.2 credit-hold release guard."""

from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    """A blocking legacy business-rule validation failure."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _legacy_number(value: Any) -> Decimal:
    """Coerce empty legacy numeric values to zero."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """Release an account credit hold subject to legacy rule ACC-004."""
    updated_account = account.copy()

    # Legacy CHAR(1) blank values mean N.
    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _legacy_number(account.get("CRED_LIMIT", "")) <= 0:
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    entity_id = account.get("ACCT_ID", "")
    if entity_id is None:
        entity_id = ""

    return updated_account, [
        {"code": "CRED_HOLD_OFF", "entity_id": str(entity_id)}
    ]
